<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/functions.php';
$pdo=db();
$categories=['Coats & jackets','Tops','Trousers & jeans','Dresses & skirts','Shoes','Children’s clothes','School uniforms','Accessories','Bedding'];
$sizes=['Baby','Children','XS','S','M','L','XL','XXL','One size']; $seasons=['All season','Spring','Summer','Autumn','Winter'];
$filters=['q'=>trim($_GET['q']??''),'category'=>$_GET['category']??'','size'=>$_GET['size']??'','season'=>$_GET['season']??'','charity'=>$_GET['charity']??'','status'=>$_GET['status']??'active'];
$where=['cr.status = ?'];$params=[$filters['status']==='all'?'active':$filters['status']];
if($filters['q']!==''){$where[]='(cr.title LIKE ? OR cr.description LIKE ? OR c.organization_name LIKE ?)';$term='%'.$filters['q'].'%';array_push($params,$term,$term,$term);}
if($filters['category']!==''){$where[]='EXISTS (SELECT 1 FROM request_requirements x WHERE x.request_id=cr.id AND x.category=?)';$params[]=$filters['category'];}
if($filters['size']!==''){$where[]='EXISTS (SELECT 1 FROM request_requirements x WHERE x.request_id=cr.id AND x.size_label=?)';$params[]=$filters['size'];}
if($filters['season']!==''){$where[]='cr.season=?';$params[]=$filters['season'];}
if(ctype_digit((string)$filters['charity'])){$where[]='cr.charity_id=?';$params[]=(int)$filters['charity'];}
$sql="SELECT cr.*,c.organization_name, COALESCE((SELECT SUM(quantity_needed) FROM request_requirements WHERE request_id=cr.id),0) needed, COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id JOIN request_requirements rr ON rr.id=di.request_requirement_id WHERE rr.request_id=cr.id AND dp.status='received'),0) received FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id WHERE ".implode(' AND ',$where)." ORDER BY FIELD(cr.urgency,'urgent','high','normal','low'),cr.created_at DESC";
$stmt=$pdo->prepare($sql);$stmt->execute($params);$requests=$stmt->fetchAll();$charities=$pdo->query('SELECT id,organization_name FROM charities WHERE verified=1 OR id IN (SELECT DISTINCT charity_id FROM clothing_requests WHERE status="active") ORDER BY organization_name')->fetchAll();
$pageTitle='Find a clothing need';require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="shell"><span class="eyebrow" style="color:#FFD928">Give with purpose</span><h1>Find the need that fits your closet.</h1><p>Search live, specific requests from local charities. Your pledge only counts as impact once it’s received.</p></div></section>
<section class="shell filter-card"><form class="filters" method="get"><input class="input" name="q" type="search" placeholder="Search a need or charity" value="<?=e($filters['q'])?>"><select class="select" name="category"><option value="">All clothing</option><?php foreach($categories as $c):?><option <?= $filters['category']===$c?'selected':'' ?>><?=e($c)?></option><?php endforeach;?></select><select class="select" name="size"><option value="">Any size</option><?php foreach($sizes as $s):?><option <?= $filters['size']===$s?'selected':'' ?>><?=e($s)?></option><?php endforeach;?></select><select class="select" name="season"><option value="">Any season</option><?php foreach($seasons as $s):?><option <?= $filters['season']===$s?'selected':'' ?>><?=e($s)?></option><?php endforeach;?></select><select class="select" name="charity"><option value="">All charities</option><?php foreach($charities as $c):?><option value="<?=$c['id']?>" <?= (string)$filters['charity']===(string)$c['id']?'selected':'' ?>><?=e($c['organization_name'])?></option><?php endforeach;?></select><button class="button button-small" type="submit">Filter</button></form></section>
<section class="section" style="padding-top:22px"><div class="shell"><div class="section-head"><h2 class="section-title"><?=count($requests)?> live <?=count($requests)===1?'request':'requests'?></h2><p class="section-description">Not sure what to offer? Start with the requests marked urgent.</p></div>
<?php if(!$requests):?><div class="empty"><span class="empty-icon">⌕</span>No needs match those filters right now. Try widening your search.</div><?php else:?><div class="request-grid"><?php foreach($requests as $request):$left=max(0,$request['needed']-$request['received']);$pct=$request['needed']?min(100,round($request['received']/$request['needed']*100)):0;?><article class="request-card"><div class="card-top"><div class="category-icon"><?=request_image_markup($request['image_path'])?></div><span class="status <?=e(status_class($request['urgency']==='urgent'?'pending':'active'))?>"><?=e($request['urgency'])?></span></div><h3><?=e($request['title'])?></h3><p><?=e($request['organization_name'])?> · <?=e($request['location'])?></p><div class="request-meta"><span class="chip"><?=e($request['season'])?></span><span class="chip chip-sun"><?=e($request['collection_location'])?></span></div><div class="progress"><span style="width:<?=$pct?>%"></span></div><div class="progress-info"><span><?=$left?> items still needed</span><span><?=$request['received']?>/<?=$request['needed']?></span></div><a class="text-link" href="<?=e(url('donor/request.php?id='.$request['id']))?>">See details & pledge →</a></article><?php endforeach;?></div><?php endif;?></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
